find_rule:
js:
var d = [];
let arr = pdfa(getResCode(), "body&&.list&&a");
for (let it of arr) {
    d.push({
        title: pdfh(it, "a&&Text").replace("视频", "音频"),
        url: pd(it, "a&&href"),
        col_type: "",
        desc: "0",
        pic_url: pd(it, "a&&pic")
    });
}
setResult(d);

detail_find_rule:
js:
var d = [];
let arr = pdfa(getResCode(), "body&&.list&&a");
for (let it of arr) {
    d.push({
        title: pdfh(it, "a&&Text"),
        url: $(pd(it, "a&&href")).lazyRule(() => {
            //使用动态解析点击时获取图片列表
            let html = request(input);
            let arr = pdfa(html, "body&&.list&&img");
            return "pics://" + arr.map(it => {
                return pd(it, "img&&src");
            }).join("&&")
        }),
        col_type: "",
        desc: "0",
    });
}
setResult(d);

